  meetings: {title:'Meetings',icon:'meet',content:() => `${heading('A useful conversation.', 'The notes, decisions and next steps, all in one place.')}<div class="demo-panel"><h3>${icon('meet')} Product sync <span class="demo-tag">Sample notes</span></h3><p class="panel-hint">October 30 · 10:00 AM · 30 min</p><div class="demo-note-summary"><strong>SUMMARY</strong><p>The team reviewed onboarding and agreed to keep the first release focused.</p><blockquote>“Let’s get the everyday flow right first.”<span class="demo-quote-source">Transcript · 08:42</span></blockquote></div><h3>Decisions & next steps</h3>${taskRow('Refine the onboarding flow','Action candidate · Review before creating a task','meeting-action')}</div><div class="demo-brief"><div>${icon('book')} Saved locally. Ready to revisit.</div><a class="demo-button" href="#features" data-jump="meetings">Explore meetings</a></div><p class="demo-freshness">Illustrative transcript and notes · No live meeting is connected</p>`},
  mail: {title:'Mail',icon:'mail',content:() => `${heading('A little less inbox.', 'Catch up, find the point and decide what comes next.')}<div class="demo-panel"><h3>${icon('mail')} Your recent inbox <span class="demo-tag">Sample messages</span></h3><div class="demo-mail-row"><span class="demo-avatar">AJ</span><div><b>Alex Jordan</b><p>Launch checklist, ready for a look</p></div><small>9:41 AM</small></div><div class="demo-mail-row"><span class="demo-avatar purple">MS</span><div><b>Maya Shah</b><p>A few thoughts from our product sync</p></div><small>Yesterday</small></div><div class="demo-mail-row"><span class="demo-avatar">LP</span><div><b>Lee Park</b><p>Next week’s agenda</p></div><small>Yesterday</small></div></div><div class="demo-brief"><div>${icon('shield')} Reading doesn’t mark mail read.</div><a class="demo-button" href="#features" data-jump="work">Explore mail</a></div><p class="demo-freshness">Illustrative messages · Gmail and Outlook connections are optional</p>`},
  developer: {title:'Developer',icon:'code',content:() => `${heading('A little more context.', 'Your project, its source and the thread of your thinking.')}<div class="demo-layout"><div class="demo-panel"><h3>${icon('folder')} Puddle <span class="demo-tag">Read-only</span></h3><div class="demo-source-tree">▾ Sources<br>　▾ PuddleCore<br>　　AssistantProfiles.swift<br>　　Agent.swift<br>　　Models.swift<br>▸ Tests<br>　Package.swift</div></div><div class="demo-panel demo-agenda-panel"><h3>${icon('code')} Saved session</h3><p class="panel-hint">Implementation · Profile simplification</p><div class="demo-note-summary"><strong>CONTEXT</strong><p>Keep useful capabilities. Simplify the profile choices.</p></div><pre class="demo-code">case personal\ncase developer\ncase custom</pre></div></div><div class="demo-brief"><div>${icon('search')} Source paths. Line numbers. Evidence.</div><a class="demo-button" href="#features" data-jump="work">Explore tools</a></div><p class="demo-freshness">Illustrative project preview · No code changes or tests are executed</p>`},
  tasks: {title:'Tasks',icon:'tasks',content:() => `${heading('The next step, in sight.', 'Choose what matters, and keep the small promises moving.')}<div class="demo-panel"><h3>${icon('tasks')} Open commitments <span class="demo-tag">Sample tasks</span></h3>${sampleTasks()}${taskRow('Follow up with the design team','Waiting on · Maya · Monday','followup')}</div><div class="demo-brief"><div>${icon('repeat')} One step at a time.</div><a class="demo-button" href="#features" data-jump="day">Explore tasks</a></div><p class="demo-freshness">Try checking off a sample task · This preview never creates a real reminder</p>`},
  calendar: {title:'Calendar',icon:'calendar',content:() => `${heading('Make room for the day.', 'Meetings when you need them. Focus time when you want it.')}<div class="demo-calendar">${['MON','TUE','WED','THU','FRI'].map((day,index) => `<div class="demo-calendar-day">${day}<b>${26+index}</b>${index===0?'<div class="demo-calendar-event">10:00<br>Planning</div>':''}${index===2?'<div class="demo-calendar-event purple">14:00<br>Focus time</div>':''}${index===4?'<div class="demo-calendar-event">10:00<br>Product sync</div><div class="demo-calendar-event purple">14:00<br>Deep work</div>':''}</div>`).join('')}</div><p class="demo-freshness">Illustrative week · Google Calendar is optional · Review changes before dispatch</p>`},
